insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000099201', '20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000265', 'multiple_choice', 'easy', 'published', 'Em uma checagem de consistência, Estude a série ou função indicada: $\sum_{n=1}^{\infty}\frac{1}{n^8}$. Qual opção descreve corretamente a estratégia e a conclusão?') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000992011', '40000000-0000-4000-8000-000000099201', 'A', 'A expressão ignora uma condição necessária do enunciado.', 1), ('50000000-0000-4000-8000-000000992012', '40000000-0000-4000-8000-000000099201', 'B', 'Converge; é uma série $p$ com $p=8>1$.', 2), ('50000000-0000-4000-8000-000000992013', '40000000-0000-4000-8000-000000099201', 'C', 'Ocorre um erro de sinal ou de ordem na etapa decisiva.', 3), ('50000000-0000-4000-8000-000000992014', '40000000-0000-4000-8000-000000099201', 'D', 'A conclusão usa uma fórmula fora de suas hipóteses.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
