insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000099235', 'O raio de convergência é $6$.', 'A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. Compare a expressão com uma série geométrica; a razão depende de $x$. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000992351', '40000000-0000-4000-8000-000000099235', 'Leia o objetivo', 'Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.', 1), ('70000000-0000-4000-8000-000000992352', '40000000-0000-4000-8000-000000099235', 'Reconheça a ideia', 'Compare a expressão com uma série geométrica; a razão depende de $x$.', 2), ('70000000-0000-4000-8000-000000992353', '40000000-0000-4000-8000-000000099235', 'Escreva a relação', 'Registre a definição, fórmula ou teste que se aplica antes de simplificar.', 3), ('70000000-0000-4000-8000-000000992354', '40000000-0000-4000-8000-000000099235', 'Desenvolva a análise', 'Execute a transformação necessária e obtenha: O raio de convergência é $6$.', 4), ('70000000-0000-4000-8000-000000992355', '40000000-0000-4000-8000-000000099235', 'Confira a conclusão', 'Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
