insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000099250', '20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000265', 'multiple_choice', 'medium', 'published', 'No momento de verificar as hipóteses, Estude a série ou função indicada: $e^x$. Selecione a única afirmação que passa pela checagem final.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000992501', '40000000-0000-4000-8000-000000099250', 'A', 'Ocorre um erro de sinal ou de ordem na etapa decisiva.', 1), ('50000000-0000-4000-8000-000000992502', '40000000-0000-4000-8000-000000099250', 'B', 'A conclusão usa uma fórmula fora de suas hipóteses.', 2), ('50000000-0000-4000-8000-000000992503', '40000000-0000-4000-8000-000000099250', 'C', 'A expressão ignora uma condição necessária do enunciado.', 3), ('50000000-0000-4000-8000-000000992504', '40000000-0000-4000-8000-000000099250', 'D', 'O polinômio de Maclaurin até grau $5$ é $\sum_{k=0}^{5}\frac{x^k}{k!}$.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000099250', '50000000-0000-4000-8000-000000992504') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
