insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000992501', '40000000-0000-4000-8000-000000099250', 'Nomeie primeiro a ideia central: Use as derivadas de $e^x$: todas valem $e^x$ e assumem valor $1$ no centro $0$.', 1), ('60000000-0000-4000-8000-000000992502', '40000000-0000-4000-8000-000000099250', 'Escreva a definição ou a relação escolhida antes de substituir os dados.', 2), ('60000000-0000-4000-8000-000000992503', '40000000-0000-4000-8000-000000099250', 'Ao final, teste se o resultado preserva as condições do enunciado e descarte erros de sinal, domínio ou hipótese.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
